197→func (a *CursorCLI) acceptTrustDialogIfNeeded(s *TmuxSession) error {
198→	// Race: either the trust dialog or the input prompt will appear first.
199→	// Use a short timeout to check for the trust dialog without blocking
200→	// too long if the workspace is already trusted.
