167→// startInteractiveSession creates a new tmux session running the Cursor CLI
168→// in interactive mode (no -p flag) so all hooks fire.
169→func (a *CursorCLI) startInteractiveSession(dir string) (*TmuxSession, error) {
170→	// Resolve to absolute path so tmux can find the binary even if its
171→	// shell doesn't inherit the test process's PATH (common on CI).
172→	bin, err := exec.LookPath(a.Binary())
173→	if err != nil {
174→		return nil, fmt.Errorf("agent binary not found: %w", err)
175→	}
176→
177→	// Create an isolated config directory for this session so parallel tests
178→	// don't race on the shared ~/.config/cursor/cli-config.json file.
179→	configDir, err := cursorConfigDir()
180→	if err != nil {
181→		return nil, fmt.Errorf("create cursor config dir: %w", err)
182→	}
183→
184→	// Build env-wrapped command so the tmux session inherits critical env vars.
185→	// tmux starts a new shell that doesn't inherit Go's os.Environ().
186→	var envArgs []string
187→	for _, key := range []string{"CURSOR_API_KEY", "PATH", "TERM"} {
188→		if v := os.Getenv(key); v != "" {
189→			envArgs = append(envArgs, key+"="+v)
190→		}
191→	}
192→	// Point XDG_CONFIG_HOME to our isolated dir so cursor writes its config
193→	// there instead of ~/.config/cursor/. Also override HOME as a fallback
194→	// since cursor may derive the config path from HOME on some platforms.
195→	envArgs = append(envArgs, "XDG_CONFIG_HOME="+configDir)
196→	envArgs = append(envArgs, "HOME="+configDir)
197→
198→	args := append([]string{"env"}, envArgs...)
199→	args = append(args, bin, "--force", "--workspace", dir)
200→
201→	name := fmt.Sprintf("cursor-cli-test-%d", time.Now().UnixNano())
202→	unset := []string{"CI"}
203→	s, err := NewTmuxSession(name, dir, unset, args[0], args[1:]...)
204→	if err != nil {
205→		_ = os.RemoveAll(configDir)
206→		return nil, err
207→	}
208→	s.OnClose(func() { _ = os.RemoveAll(configDir) })
209→	return s, nil
210→}
211→
212→// acceptTrustDialogIfNeeded checks whether the workspace trust dialog appears
213→// and presses "a" to accept it. The dialog only shows on the first launch in
214→// a workspace — subsequent sessions in the same directory skip it.
215→func (a *CursorCLI) acceptTrustDialogIfNeeded(s *TmuxSession) error {
216→	// Race: either the trust dialog or the input prompt will appear first.
217→	// Use a short timeout to check for the trust dialog without blocking
218→	// too long if the workspace is already trusted.
219→	content, err := s.WaitFor(`Trust this workspace|`+a.PromptPattern(), 30*time.Second)
220→	if err != nil {
221→		return fmt.Errorf("waiting for trust dialog or prompt: %w", err)
222→	}
223→	if strings.Contains(content, "Trust this workspace") {
224→		if err := s.SendKeys("a"); err != nil {
225→			return fmt.Errorf("accepting trust dialog: %w", err)
226→		}
227→	}
228→	return nil
229→}
